        _this.capacity = _p2;
        _this.entries = (z_t3736_entry_t*)z_xcalloc(
            z_t3736_entries_cap(_p2), sizeof(z_t3736_entry_t));
        if (_p2 > Z_T3736_SMALL_MAX) {
            _this.indices = (uint32_t*)z_xcalloc(_p2, sizeof(uint32_t));
        }
