    if (consumed != self->size) {
        out.tag = Z_T10268_TAG_0;
        out.data.a0 = Z_T9928_TAG_1;
        return out;
    }
    if (err == ERANGE) {
        out.tag = Z_T10268_TAG_0;
        out.data.a0 = Z_T9928_TAG_2;
        return out;
    }
    out.tag = Z_T10268_TAG_1;
    out.data.a1 = v;
    return out;
