        z_t3393_t* boxed = (z_t3393_t*)z_xmalloc(sizeof(z_t3393_t));
        *boxed = z_io_errno_to_IoError(e);
        result.tag = Z_T4423_TAG_0;
        result.data = boxed;
        return result;
